-- Local-only seed, applied by `supabase db reset`. Hosted projects never run this file.

-- Where the database finds the send-push Edge Function (see migrations 009 and 010). `kong` is
-- the API gateway's hostname inside the local Docker network. A hosted project sets this secret
-- to its own functions URL instead; see docs/architecture/push-notifications.md. The dispatch
-- secret is generated by migration 010, so nothing else needs seeding.
SELECT vault.create_secret('http://kong:8000/functions/v1', 'codeword_functions_url');
